public void addTotal(String cat, int amt) {
		int current = categoryTotals.containsKey(cat) ? categoryTotals.get(cat) : 0;
		current += amt;
		if (current <= 0)
			categoryTotals.remove(cat);
		else
			categoryTotals.put(cat, current);
	}

