@SubscribeEvent
	public static void clientTick(TickEvent.ClientTickEvent event) {
		if (event.phase != TickEvent.Phase.END) {
			return;
		}

		ticking = true;
		synchronized (lock) {
			ticking = true;
			Iterator<QueueEntry> iterator = queue.iterator();
			while (iterator.hasNext()) {
				QueueEntry entry = iterator.next();
				if (entry.counter-- <= 0) {
					entry.runnable.run();
					iterator.remove();
				}
			}
			ticking = false;
			for (WaitEntry entry : waitlist) {
				queue.addLast(new QueueEntry(entry.runnable, entry.delay));
			}
		}
		waitlist.clear();
	}

public static void addRunnable(Runnable runnable) {
		addRunnable(runnable, 0);
	}

public static void addRunnable(Runnable runnable, int delay) {
		synchronized (lock) {
			if (ticking) {
				waitlist.addLast(new WaitEntry(runnable, delay));
			} else {
				queue.addLast(new QueueEntry(runnable, delay));
			}
		}
	}

public WaitEntry(Runnable runnable, int delay) {
			this.runnable = runnable;
			this.delay = delay;
		}

public QueueEntry(Runnable runnable, int counter) {
			this.runnable = runnable;
			this.counter = counter;
		}

public static void tick(TickEvent.ClientTickEvent event) {
		if (event.phase == TickEvent.Phase.END) {
			PatchouliHack.timer.onDraw();
		}
	}

@SubscribeEvent
	public static void onDeath(LivingDeathEvent event) {
		if (!GeneralConfig.UntruePacifist) {
			return;
		}
		EntityLivingBase entity = event.getEntityLiving();
		PacifistEntry entry = ModRecipes.getPacifistEntry(entity);
		if (entry == null || !entity.isServerWorld()) return;

		DamageSource source = event.getSource();
		if (!(source instanceof EntityDamageSource)) return;
		Entity trueSource = source.getTrueSource();
		if (!(trueSource instanceof EntityPlayerMP)) return;

		if (!entry.matches(entity, (EntityPlayer) trueSource)) return;

		if (entity.getControllingPassenger() != null) return;

		List<Entity> entities = entity.getEntityWorld().getEntitiesInAABBexcluding(entity, BOUNDING_BOX.offset(entity.getPosition()), o -> EntityUtil.isHostileTo(entity, (EntityPlayer) trueSource));
		if (!entities.isEmpty()) {
			return;
		}

		Advancements.PACIFIST_TRIGGER.trigger((EntityPlayerMP) trueSource, event);
	}

@SubscribeEvent
	public static void onLivingDrop(LivingDropsEvent event) {
		DamageSource source = event.getSource();
		Entity entity = source.getTrueSource();
		if (entity instanceof EntityPlayer) {
			EntityLivingBase dying = event.getEntityLiving();
			NBTTagCompound data = dying.getEntityData();
			if (data.hasKey("magnetic_ticks", Constants.NBT.TAG_INT)) {
				int ticks = data.getInteger("magnetic_ticks");
				if (ticks < dying.ticksExisted || (dying.ticksExisted - ticks) < 3 * 20) {
					if (data.hasUniqueId("magnetic")) {
						UUID id = data.getUniqueId("magnetic");
						if (id != null && id.equals(entity.getUniqueID())) {
							for (EntityItem item : event.getDrops()) {
								item.setPosition(entity.posX, entity.posY, entity.posZ);
								entity.world.spawnEntity(item);
							}
							event.setCanceled(true);
						}
					}
				}
			}
		}
	}

