private boolean isWaterAround(BlockPos pos, World world) {
		for (EnumFacing dir : EnumFacing.HORIZONTALS) {
			Block block = world.getBlockState(pos.offset(dir)).getBlock();
			if (GeneralConfig.getWaterBlocks().contains(block)) {
				return true;
			}
		}
		return false;
	}

