public static float[] getColor(int elementId) {
		int r, g, b;

		switch (elementId) {
			//Fire
			case 0:
				r = 196;
				g = 90;
				b = 13;
				break;
			//Water
			case 1:
				r = 43;
				g = 159;
				b = 206;
				break;
			//Air
			case 2:
				r = 164;
				g = 196;
				b = 203;
				break;
			//Earth
			case 3:
				r = 81;
				g = 55;
				b = 8;
				break;
			//CHAOS (NULL) >:)
			default:
				r = 0;
				g = 0;
				b = 0;
		}

		return new float[]{r / 255.0f, g / 255.0f, b / 255.0f, 0.75f};
	}

