									pos.getZ() + (0.5f - world.rand.nextFloat()) + (world.rand.nextInt(3) == 0 ? (world.rand.nextBoolean() ? -1 : 1) : 0),
									0, 0, 0, type.getColor(), 10f, 20 * 30, true);
