		if (ModRecipes.findSummonCreatureEntry(plateItems) != null) {
			return true;
		}

		for (ItemStack stack : plateItems) {
			if (stack.getItem() == ModItems.life_essence) {
				return true;
			}
		}

		return false;
	}

