public static boolean shouldPlaySound(EntityPlayer player) {
		long val = soundTimer.getLong(player);
		if (val == -1) {
			soundTimer.put(player, player.ticksExisted);
			return true;
		}
		if (player.ticksExisted >= val + DELAY || player.ticksExisted < val) {
			soundTimer.put(player, player.ticksExisted);
			return true;
		}
		return false;
	}

