@Nullable
	public RayTraceResult rayTrace(EntityPlayer player, double blockReachDistance, boolean ignore) {
		Vec3d vec3d = player.getPositionEyes(1.0F);
		Vec3d vec3d1 = player.getLook(1.0F);
