@Override
	public void update() {
		if (world.isRemote && world.getTotalWorldTime() % 2 == 0 && getRecipe() != null) {
			ClientProxy.particleRenderer.spawnParticle(
					world,
					ParticleLeaf.class,
					(double) pos.getX() + 0.5D,
					(double) pos.getY() + 0.75D,
					(double) pos.getZ() + 0.5D,
					(Util.rand.nextDouble() - 0.5) * 0.005,
					(Util.rand.nextDouble() * 0.02) * 0.5,
					(Util.rand.nextDouble() - 0.5) * 0.005,
					100,
					63 / 255.0,
					(143 / 255.0) + Util.rand.nextDouble() * 0.05,
					74 / 255.0,
					1, //0.785,
					1,
					1
			);
		}
		if (!world.isRemote) {
			if (countdown > 0) {
				if (storedItems.isEmpty()) {
					countdown = -1;
				} else {
					countdown--;
				}
			} else {
				countdown = -1;
				for (EnumFacing facing : EnumFacing.values()) {
					IBlockState state = world.getBlockState(getPos().offset(facing));
					if (GeneralConfig.getCrafterOutputIgnore().contains(state.getBlock())) {
						continue;
					}
					TileEntity te = world.getTileEntity(getPos().offset(facing));
					if (te != null) {
						IItemHandler cap = te.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY, null);
						if (cap != null) {
							List<ItemStack> newItems = new ArrayList<>();
							for (ItemStack toPut : storedItems) {
								ItemStack result = ItemHandlerHelper.insertItemStacked(cap, toPut, false);
								if (!result.isEmpty()) {
									newItems.add(result);
								}
							}
							storedItems = newItems;
						}
					}
				}
				for (ItemStack stack : storedItems) {
					EntityItem item = new EntityItem(world, pos.getX() + 0.5, pos.getY() + 1.1, pos.getZ() + 0.5, stack);
					world.spawnEntity(item);
				}
				this.storedItems.clear();
			}
		}
	}

@Override
	public void render(TileEntityFeyCrafter te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {

		List<ItemStack> items = new ArrayList<>();

		for (int i = 0; i < te.inventory.getSlots(); i++)
			items.add(te.inventory.getStackInSlot(i));

		for (ItemStack item : items) {

			if (item.isEmpty())
				continue;

			GlStateManager.pushMatrix();
			RenderHelper.enableStandardItemLighting();
			//Dunno how much I need this ^^^


			switch (items.indexOf(item)) {
				case 0:
					GlStateManager.translate(x + 0.5, y + 1.1, z + 0.125);
					break;
				case 1:
					GlStateManager.translate(x + 0.13, y + 1.1, z + 0.45);
					break;
				case 2:
					GlStateManager.translate(x + 0.88, y + 1.1, z + 0.45);
					break;
				case 3:
					GlStateManager.translate(x + 0.25, y + 1.1, z + 0.88);
					break;
				case 4:
					GlStateManager.translate(x + 0.69, y + 1.1, z + 0.88);
					break;
			}

			GlStateManager.scale(0.45, 0.45, 0.45);
			GlStateManager.rotate((te.getWorld().getTotalWorldTime() + partialTicks) * 4, 0, 1, 0);

			// Old rotation (Items laid on the leaves)
//      GlStateManager.rotate(90, 1, 0, 0);
//      GlStateManager.rotate(-90, 0, 0, 1);

			Minecraft.getMinecraft().getRenderItem().renderItem(item, ItemCameraTransforms.TransformType.GROUND);

			RenderHelper.disableStandardItemLighting();
			GlStateManager.popMatrix();

			FeyCraftingRecipe recipe = te.getRecipe();
			if (recipe != null) {
				renderResult((te.getWorld().getTotalWorldTime() + partialTicks) * 2.6f, x, y, z, recipe.getResult(), 0.99f);
			}
		}
	}

private void renderResult(float ticks, double x, double y, double z, ItemStack result, float alpha) {
		GlStateManager.enableBlend();
		RenderHelper.enableStandardItemLighting();
		GlStateManager.enableRescaleNormal();
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + 0.5, y + 1.4, z + 0.5);
		GlStateManager.scale(0.3, 0.3, 0.3);
		GlStateManager.rotate(ticks, 0, 1, 0);

		Minecraft mc = Minecraft.getMinecraft();
		RenderItem ri = mc.getRenderItem();
		TextureManager tm = mc.getTextureManager();

		IBakedModel bakedmodel = ri.getItemModelWithOverrides(result, null, null);
		tm.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		tm.getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).setBlurMipmap(false, false);
		GlStateManager.pushMatrix();
		ri.renderItem(result, bakedmodel);
		GlStateManager.cullFace(GlStateManager.CullFace.BACK);
		GlStateManager.popMatrix();
		GlStateManager.disableRescaleNormal();
		GlStateManager.disableBlend();
		tm.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		tm.getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).restoreLastBlurMipmap();

		GlStateManager.popMatrix();
		GlStateManager.color(1F, 1F, 1F, 1F);
	}

